const details = await browserjs(tabId, () => {
  const placards = Array.from(document.querySelectorAll('article.placard, li.mortar-wrapper, .placardContainer .placard'));

  const results = [];
  const seenUrls = new Set();

  for (const p of placards) {
    const titleEl = p.querySelector('.property-title') || p.querySelector('.title') || p.querySelector('a.property-link span');
    const addressEl = p.querySelector('.property-address') || p.querySelector('.address');
    const pricingEl = p.querySelector('.property-pricing') || p.querySelector('.price-range') || p.querySelector('.property-rents');
    const bedsEl = p.querySelector('.property-beds') || p.querySelector('.beds');
    const linkEl = p.querySelector('a.property-link');

    const url = linkEl?.href;
    if (url && seenUrls.has(url)) continue;
    if (url) seenUrls.add(url);

    const name = titleEl ? titleEl.innerText.trim() : (linkEl ? linkEl.getAttribute('aria-label') || linkEl.innerText.trim() : '');
    const address = addressEl ? addressEl.innerText.trim() : '';
    const price = pricingEl ? pricingEl.innerText.trim() : '';
    const beds = bedsEl ? bedsEl.innerText.trim() : '';

    if (name || address) {
      results.push({ name, address, price, beds, url });
    }
  }

  // Also get the search summary text
  const searchSummary = document.querySelector('.pageRange, .results, .search-header-subtitle, h1')?.innerText;

  return { searchSummary, count: results.length, results };
});

