  const placards = Array.from(document.querySelectorAll('article.placard, li.mortar-wrapper, .placard'));
  const seen = new Set();
  const listings = [];

  for (const p of placards) {
    const link = p.querySelector('a.property-link');
    const url = link?.href;
    if (!url || seen.has(url)) continue;
    seen.add(url);

    const textLines = p.innerText.split('\n').map(s => s.trim()).filter(Boolean);
    const title = p.querySelector('.property-title, .title')?.innerText?.trim() || textLines[0];
    const address = p.querySelector('.property-address, .address')?.innerText?.trim() || textLines[1];

    // Find lines with dollar amounts
    const priceLines = textLines.filter(line => line.startsWith('$') || line.includes('$'));

    listings.push({
      title,
      address,
      url,
      textLines,
      priceLines
    });
  }

  const pageTitle = document.title;
  const currentUrl = window.location.href;
  const header = document.querySelector('h1')?.innerText;

  return {
    pageTitle,
    currentUrl,
    header,
    count: listings.length,
    listings
  };
});

